// GlanceMap findings: source-checked study values paired with their interpretation.
// No SVG. Bars and connecting rules are HTML/CSS, preserving a shared 0–100% scale.
import { DATA_VISUAL_REPLACEMENTS } from './data-viz.js';
const esc=(s='')=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const recall=DATA_VISUAL_REPLACEMENTS.find(x=>x.projectId==='glancemap'&&x.visual.id==='glance-recall').visual;
const recognition=DATA_VISUAL_REPLACEMENTS.find(x=>x.projectId==='glancemap'&&x.visual.id==='glance-recognition').visual;
const results=[
 {id:'immediate',name:'Immediate free recall',panel:recall.panels[0],delta:'+9.6 pp',summary:'More remembered right away',body:'Lesson content recalled without prompts.'},
 {id:'day-seven',name:'Day-7 free recall',panel:recall.panels[1],delta:'+7.0 pp',summary:'Better recall after seven days',body:'The same recall task, one week later.'},
 {id:'pictures',name:'Picture recognition',panel:recognition.panels[0],delta:'−7.1 pp',summary:'Less picture recognition',body:'Recognizing seen pictures, rather than recalling lesson content.'}
];
function heading(s,i,title){return `<div class="section-heading"><div class="eyebrow"><span>${String(i+1).padStart(2,'0')}</span> / ${esc(s.nav||s.id)}</div><h2>${esc(title||s.title)}</h2></div>`;}
function pair(r){return `<article class="gr-result-pair" tabindex="0" aria-labelledby="gr-${r.id}-title"><div class="gr-evidence"><h3 id="gr-${r.id}-title">${r.name}</h3><div class="gr-bars">${r.panel.rows.map(row=>`<div class="gr-bar-row" data-series="${row.series}" data-winner="${row.value===Math.max(...r.panel.rows.map(v=>v.value))}"><div class="gr-bar-label"><span>${row.label}</span><strong aria-label="${row.display}"><span data-gr-number="${row.value}" aria-hidden="true">${Number(row.value).toFixed(1)}</span><span aria-hidden="true">%</span></strong></div><div class="gr-track" aria-hidden="true"><span style="--gr-width:${row.value}%"></span></div></div>`).join('')}</div><div class="gr-axis" aria-hidden="true"><span>0%</span><span>100%</span></div></div><div class="gr-connector" aria-hidden="true"><span></span></div><div class="gr-interpretation"><span class="gr-difference">${r.delta}</span><h3>${r.summary}</h3><p>${r.body}</p></div></article>`;}
export function renderGlanceResults(s,i=0){
 if(s.id==='findings')return `<section id="findings" class="case-section glance-results" data-glance-results>${heading(s,i)}<div class="gr-pairs">${results.map(pair).join('')}</div><div class="gr-secondary"><div><strong>+1.59 <span>/ 7-point scale</span></strong><h3>Clearer lesson structure</h3></div><div><strong>Walking</strong><h3>No detectable gait difference</h3><p>Cadence and gait stability.</p></div><div><strong>Workload</strong><h3>A modest increase</h3><p>Results depended on the analysis model.</p></div></div><details class="gr-study-note"><summary>About these measurements</summary><p>16 participants. Recall bars show material-adjusted mean scores on the same 0–100% scale. “pp” means percentage points.</p><p>Picture recognition: Illustration Only, 93/112 responses (83.0%); GlanceMap, 85/112 (75.9%). This comparison does not isolate which individual interface component caused the change.</p></details></section>`;
 if(s.id==='next')return `<section id="next" class="case-section glance-next-steps">${heading({...s,nav:'Discussion'},i,'What to test next')}<div class="gr-next-head" aria-hidden="true"><span>Study limit</span><span>Next step</span></div><ol class="gr-next-list"><li><div><h3>One integrated system</h3></div><div><p>Test <strong>each component separately</strong>, including a mind-map-only version.</p></div></li><li><div><h3>One indoor route</h3></div><div><p>Try <strong>outdoor walking</strong> and a wider range of users.</p></div></li><li><div><h3>Prepared audio lessons</h3></div><div><p>Explore <strong>live speech</strong> with stable layouts and low delay.</p></div></li></ol></section>`;
 return null;
}
export function setupGlanceResults(root=document){
 const rows=[...root.querySelectorAll('.gr-result-pair')];const frames=new Set();
 const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 function animate(row){row.classList.add('gr-shown');if(reduced)return;const start=performance.now();row.querySelectorAll('[data-gr-number]').forEach(node=>{let frame;const target=Number(node.dataset.grNumber);function tick(now){frames.delete(frame);if(!node.isConnected)return;const t=Math.min(1,(now-start)/750);node.textContent=(target*(1-Math.pow(1-t,3))).toFixed(1);if(t<1){frame=requestAnimationFrame(tick);frames.add(frame);}}frame=requestAnimationFrame(tick);frames.add(frame);});}
 let observer;if('IntersectionObserver'in window){observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){animate(e.target);observer.unobserve(e.target);}}),{threshold:.25});rows.forEach(row=>observer.observe(row));}else rows.forEach(animate);
 return()=>{observer?.disconnect();frames.forEach(cancelAnimationFrame);};
}
